from camoufox import Camoufox
import time

with Camoufox(headless=True).start() as browser:
    page = browser.new_page()

    # Try different finance sites
    urls = [
        ("MarketWatch", "https://www.marketwatch.com/investing/stock/dhr"),
        ("Zacks", "https://www.zacks.com/stock/quote/DHR"),
        ("CNN Business", "https://www.cnn.com/business/stock-markets"),
        ("CNBC DHR", "https://www.cnbc.com/quotes/DHR"),
    ]

    for label, url in urls:
        try:
            page.goto(url, timeout=15000)
            time.sleep(3)
            text = page.inner_text("body")
            if text and len(text) > 100:
                lines = [l.strip() for l in text.split("\n") if l.strip() and len(l.strip()) > 5]
                print(f"\n=== {label} ({len(text)} chars) ===")
                # Show first meaningful lines
                for l in lines[1:30]:
                    if len(l) > 10:
                        print(l)
            else:
                print(f"\n=== {label}: Empty or blocked ===")
        except Exception as e:
            print(f"\n=== {label}: ERROR {e} ===")
EOF"}

